const cudaCoreFiles={"cuda_lab.cu":"// Original educational CUDA kernels. Compilation alone is not GPU execution.\n#include <cuda_runtime.h>\n#include <math_constants.h>\n#include <algorithm>\n#include <cmath>\n#include <cstdint>\n#include <fstream>\n#include <iomanip>\n#include <iostream>\n#include <limits>\n#include <sstream>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\n#ifndef GUIDE_SOURCE_SHA256\n#define GUIDE_SOURCE_SHA256 \"unbound\"\n#endif\nconstexpr int SUM_THREADS = 256;\nconstexpr int SOFTMAX_THREADS = 128;\nconstexpr int TILE = 16;\n\n// One block owns a complete row; inactive lanes contribute the additive identity.\nextern \"C\" __global__ void row_sum_kernel(const float* x, float* y, int cols) {\n    __shared__ float partial[SUM_THREADS];\n    const int row = blockIdx.x, lane = threadIdx.x;\n    float sum = 0.0f;\n    for (int col = lane; col < cols; col += SUM_THREADS)\n        sum += x[static_cast<size_t>(row) * cols + col];\n    partial[lane] = sum;\n    __syncthreads();\n    for (int stride = SUM_THREADS / 2; stride > 0; stride /= 2) {\n        if (lane < stride) partial[lane] += partial[lane + stride];\n        __syncthreads();\n    }\n    if (lane == 0) y[row] = partial[0];\n}\n\n// Separate shared arrays retain max until every lane has consumed it.\nextern \"C\" __global__ void row_softmax_kernel(const float* x, float* y,\n                                              int cols, bool normalize) {\n    __shared__ float maxima[SOFTMAX_THREADS];\n    __shared__ float totals[SOFTMAX_THREADS];\n    const int row = blockIdx.x, lane = threadIdx.x;\n    const size_t offset = static_cast<size_t>(row) * cols;\n    float maximum = -CUDART_INF_F;\n    for (int col = lane; col < cols; col += SOFTMAX_THREADS)\n        maximum = fmaxf(maximum, x[offset + col]);\n    maxima[lane] = maximum;\n    __syncthreads();\n    for (int stride = SOFTMAX_THREADS / 2; stride > 0; stride /= 2) {\n        if (lane < stride) maxima[lane] = fmaxf(maxima[lane], maxima[lane + stride]);\n        __syncthreads();\n    }\n    maximum = maxima[0];\n    float total = 0.0f;\n    for (int col = lane; col < cols; col += SOFTMAX_THREADS)\n        total += expf(x[offset + col] - maximum);\n    totals[lane] = total;\n    __syncthreads();\n    for (int stride = SOFTMAX_THREADS / 2; stride > 0; stride /= 2) {\n        if (lane < stride) totals[lane] += totals[lane + stride];\n        __syncthreads();\n    }\n    const float denominator = totals[0];\n    for (int col = lane; col < cols; col += SOFTMAX_THREADS) {\n        const float numerator = expf(x[offset + col] - maximum);\n        y[offset + col] = normalize ? numerator / denominator : numerator;\n    }\n}\n\n// Out-of-range lanes still load zeros and participate in both barriers.\nextern \"C\" __global__ void tiled_matmul_kernel(const float* a, const float* b,\n                                               float* c, int m, int k, int n) {\n    __shared__ float a_tile[TILE][TILE];\n    __shared__ float b_tile[TILE][TILE];\n    const int row = blockIdx.y * TILE + threadIdx.y;\n    const int col = blockIdx.x * TILE + threadIdx.x;\n    float value = 0.0f;\n    for (int base = 0; base < k; base += TILE) {\n        const int a_col = base + threadIdx.x, b_row = base + threadIdx.y;\n        a_tile[threadIdx.y][threadIdx.x] = (row < m && a_col < k)\n            ? a[static_cast<size_t>(row) * k + a_col] : 0.0f;\n        b_tile[threadIdx.y][threadIdx.x] = (b_row < k && col < n)\n            ? b[static_cast<size_t>(b_row) * n + col] : 0.0f;\n        __syncthreads();\n        for (int inner = 0; inner < TILE; ++inner)\n            value = fmaf(a_tile[threadIdx.y][inner], b_tile[inner][threadIdx.x], value);\n        __syncthreads();\n    }\n    if (row < m && col < n) c[static_cast<size_t>(row) * n + col] = value;\n}\n\nstatic void require(bool condition, const std::string& message) {\n    if (!condition) throw std::runtime_error(message);\n}\nstatic void checked(cudaError_t error, const char* operation) {\n    if (error != cudaSuccess)\n        throw std::runtime_error(std::string(operation) + \": \" + cudaGetErrorString(error));\n}\nstruct Buffer {\n    float* data = nullptr;\n    explicit Buffer(size_t elements) {\n        require(elements > 0 && elements <= std::numeric_limits<size_t>::max() / sizeof(float), \"invalid_allocation_size\");\n        checked(cudaMalloc(reinterpret_cast<void**>(&data), elements * sizeof(float)), \"cudaMalloc\");\n    }\n    ~Buffer() { if (data) (void)cudaFree(data); }\n    Buffer(const Buffer&) = delete;\n    Buffer& operator=(const Buffer&) = delete;\n};\nstatic std::string quoted(const std::string& value) {\n    std::ostringstream out;\n    out << '\"';\n    for (unsigned char ch : value) {\n        if (ch == '\"' || ch == '\\\\') out << '\\\\' << ch;\n        else if (ch < 32) out << \"\\\\u\" << std::hex << std::setw(4) << std::setfill('0') << unsigned(ch) << std::dec;\n        else out << ch;\n    }\n    out << '\"';\n    return out.str();\n}\ntemplate <typename T> static std::string array(const std::vector<T>& values) {\n    std::ostringstream out;\n    out << std::setprecision(17) << '[';\n    for (size_t i = 0; i < values.size(); ++i) { if (i) out << ','; out << values[i]; }\n    out << ']';\n    return out.str();\n}\nstatic void emit(const std::string& report, const std::string& filename) {\n    if (!filename.empty()) {\n        std::ofstream file(filename);\n        require(bool(file), \"cannot_open_output\");\n        file << report << '\\n';\n        require(bool(file), \"cannot_write_output\");\n    }\n    std::cout << report << '\\n';\n}\nstatic std::vector<float> rows(int count, int cols) {\n    std::vector<float> x(static_cast<size_t>(count) * cols);\n    for (int row = 0; row < count; ++row)\n        for (int col = 0; col < cols; ++col)\n            x[static_cast<size_t>(row) * cols + col] = (((row + 1) * 11 + col * 7) % 29 - 14) / 4.0f + row * 0.125f;\n    return x;\n}\nstatic std::vector<double> sum_reference(const std::vector<float>& x, int count, int cols) {\n    std::vector<double> y(count, 0.0);\n    for (int row = 0; row < count; ++row)\n        for (int col = 0; col < cols; ++col) y[row] += double(x[static_cast<size_t>(row) * cols + col]);\n    return y;\n}\nstatic std::vector<double> softmax_reference(const std::vector<float>& x, int count, int cols) {\n    std::vector<double> y(x.size());\n    for (int row = 0; row < count; ++row) {\n        const size_t base = static_cast<size_t>(row) * cols;\n        double maximum = x[base], total = 0;\n        for (int col = 1; col < cols; ++col) maximum = std::max(maximum, double(x[base + col]));\n        for (int col = 0; col < cols; ++col) { y[base + col] = std::exp(double(x[base + col]) - maximum); total += y[base + col]; }\n        for (int col = 0; col < cols; ++col) y[base + col] /= total;\n    }\n    return y;\n}\nstatic double max_error(const std::vector<float>& actual, const std::vector<double>& expected) {\n    require(actual.size() == expected.size(), \"output_size_mismatch\");\n    double maximum = 0;\n    for (size_t i = 0; i < actual.size(); ++i) {\n        require(std::isfinite(actual[i]), \"nonfinite_device_output\");\n        maximum = std::max(maximum, std::abs(double(actual[i]) - expected[i]));\n    }\n    return maximum;\n}\nstatic bool agrees(const std::vector<float>& actual, const std::vector<double>& expected) {\n    if (actual.size() != expected.size()) return false;\n    for (size_t i = 0; i < actual.size(); ++i)\n        if (!std::isfinite(actual[i]) || std::abs(double(actual[i]) - expected[i]) > 1e-5 + 1e-5 * std::abs(expected[i])) return false;\n    return true;\n}\nstatic std::vector<float> run_rows(const std::vector<float>& x, int count, int cols, bool softmax, bool normalize = true) {\n    const size_t size = softmax ? x.size() : static_cast<size_t>(count);\n    Buffer input(x.size()), output(size);\n    checked(cudaMemcpy(input.data, x.data(), x.size() * sizeof(float), cudaMemcpyHostToDevice), \"copy_rows_to_device\");\n    if (softmax) row_softmax_kernel<<<count, SOFTMAX_THREADS>>>(input.data, output.data, cols, normalize);\n    else row_sum_kernel<<<count, SUM_THREADS>>>(input.data, output.data, cols);\n    checked(cudaGetLastError(), \"row_kernel_launch\");\n    checked(cudaDeviceSynchronize(), \"row_kernel_execution\");\n    std::vector<float> actual(size);\n    checked(cudaMemcpy(actual.data(), output.data, size * sizeof(float), cudaMemcpyDeviceToHost), \"copy_rows_to_host\");\n    return actual;\n}\nstruct MatrixResult { std::vector<float> actual; std::vector<double> expected; };\nstatic MatrixResult run_gemm(int m, int k, int n) {\n    std::vector<float> a(static_cast<size_t>(m) * k), b(static_cast<size_t>(k) * n);\n    for (int row = 0; row < m; ++row) for (int col = 0; col < k; ++col)\n        a[static_cast<size_t>(row) * k + col] = ((row * 3 + col * 5) % 17 - 8) / 8.0f;\n    for (int row = 0; row < k; ++row) for (int col = 0; col < n; ++col)\n        b[static_cast<size_t>(row) * n + col] = ((row * 7 + col * 2) % 19 - 9) / 16.0f;\n    Buffer da(a.size()), db(b.size()), dc(static_cast<size_t>(m) * n);\n    checked(cudaMemcpy(da.data, a.data(), a.size() * sizeof(float), cudaMemcpyHostToDevice), \"copy_a\");\n    checked(cudaMemcpy(db.data, b.data(), b.size() * sizeof(float), cudaMemcpyHostToDevice), \"copy_b\");\n    const dim3 block(TILE, TILE), grid((n + TILE - 1) / TILE, (m + TILE - 1) / TILE);\n    tiled_matmul_kernel<<<grid, block>>>(da.data, db.data, dc.data, m, k, n);\n    checked(cudaGetLastError(), \"gemm_launch\");\n    checked(cudaDeviceSynchronize(), \"gemm_execution\");\n    MatrixResult result{std::vector<float>(static_cast<size_t>(m) * n), std::vector<double>(static_cast<size_t>(m) * n, 0.0)};\n    checked(cudaMemcpy(result.actual.data(), dc.data, result.actual.size() * sizeof(float), cudaMemcpyDeviceToHost), \"copy_c\");\n    for (int row = 0; row < m; ++row) for (int col = 0; col < n; ++col)\n        for (int inner = 0; inner < k; ++inner)\n            result.expected[static_cast<size_t>(row) * n + col] += double(a[static_cast<size_t>(row) * k + inner]) * double(b[static_cast<size_t>(inner) * n + col]);\n    return result;\n}\nstatic std::string result(const std::string& name, const std::vector<int>& shape,\n                          const std::vector<float>& actual, const std::vector<double>& expected,\n                          bool include_values = true) {\n    require(agrees(actual, expected), \"numerical_mismatch:\" + name);\n    std::ostringstream out;\n    out << std::setprecision(17) << \"{\\\"fixture\\\":\" << quoted(name) << \",\\\"shape\\\":\" << array(shape)\n        << \",\\\"elements\\\":\" << actual.size() << \",\\\"max_abs_error\\\":\" << max_error(actual, expected)\n        << \",\\\"values\\\":\" << (include_values ? array(actual) : \"[]\") << '}';\n    return out.str();\n}\nint main(int argc, char** argv) {\n    std::string filename;\n    bool probe_only = false, profile_gemm = false;\n    try {\n        for (int i = 1; i < argc; ++i) {\n            const std::string arg = argv[i];\n            if (arg == \"--help\") {\n                std::cout << \"cuda_lab [--json FILE] [--probe-only | --profile-gemm]\\n\"\n                             \"Default: 13 small GPU correctness fixtures plus a bad-softmax rejection.\\n\"\n                             \"--probe-only queries availability without launching a kernel.\\n\"\n                             \"--profile-gemm selects one 512x512 GEMM, not the complete correctness suite.\\n\";\n                return 0;\n            } else if (arg == \"--json\" && i + 1 < argc) filename = argv[++i];\n            else if (arg == \"--probe-only\") probe_only = true;\n            else if (arg == \"--profile-gemm\") profile_gemm = true;\n            else throw std::runtime_error(\"unknown_or_incomplete_argument:\" + arg);\n        }\n        require(!(probe_only && profile_gemm), \"choose_probe_or_profile\");\n        int device_count = 0;\n        const auto probe = cudaGetDeviceCount(&device_count);\n        if (probe_only || probe != cudaSuccess || device_count == 0) {\n            const bool available = probe == cudaSuccess && device_count > 0;\n            emit(\"{\\\"status\\\":\" + quoted(available ? \"device-detected\" : \"not-run\") +\n                 \",\\\"device_execution\\\":false,\\\"device_count\\\":\" + std::to_string(device_count) +\n                 \",\\\"source_sha256\\\":\" + quoted(GUIDE_SOURCE_SHA256) +\n                 \",\\\"cuda_probe\\\":\" + quoted(cudaGetErrorString(probe)) + \"}\", filename);\n            return available ? 0 : 2;\n        }\n        checked(cudaSetDevice(0), \"select_device\");\n        cudaDeviceProp device{};\n        checked(cudaGetDeviceProperties(&device, 0), \"device_properties\");\n        require(device.major >= 8, \"requires_compute_capability_8_or_newer\");\n        require(device.maxThreadsPerBlock >= 256 && device.sharedMemPerBlock >= 2048, \"insufficient_block_resources\");\n        int runtime = 0, driver = 0;\n        checked(cudaRuntimeGetVersion(&runtime), \"runtime_version\");\n        checked(cudaDriverGetVersion(&driver), \"driver_version\");\n        std::vector<std::string> results;\n        std::vector<float> wrong;\n        if (profile_gemm) {\n            const auto g = run_gemm(512, 512, 512);\n            results.push_back(result(\"profile-gemm-512\", {512,512,512}, g.actual, g.expected, false));\n        } else {\n            for (int cols : {1, 5, 129, 257}) {\n                const auto x = rows(3, cols);\n                results.push_back(result(\"sum-\" + std::to_string(cols), {3,cols}, run_rows(x,3,cols,false), sum_reference(x,3,cols)));\n                results.push_back(result(\"softmax-\" + std::to_string(cols), {3,cols}, run_rows(x,3,cols,true), softmax_reference(x,3,cols)));\n            }\n            const std::vector<float> extreme{1000,1001,999,-1000,0};\n            const auto reference = softmax_reference(extreme,1,5);\n            results.push_back(result(\"softmax-extreme\", {1,5}, run_rows(extreme,1,5,true), reference));\n            wrong = run_rows(extreme,1,5,true,false);\n            require(!agrees(wrong,reference), \"negative_control_was_not_rejected\");\n            for (const std::vector<int> shape : {std::vector<int>{1,1,1}, {17,19,13}, {32,32,32}, {31,33,29}}) {\n                const auto g = run_gemm(shape[0],shape[1],shape[2]);\n                results.push_back(result(\"gemm-\" + std::to_string(shape[0]) + \"-\" + std::to_string(shape[1]) + \"-\" + std::to_string(shape[2]), shape, g.actual, g.expected));\n            }\n        }\n        std::ostringstream report;\n        report << \"{\\\"schema_version\\\":1,\\\"status\\\":\\\"passed\\\",\\\"device_execution\\\":true,\\\"profile_only\\\":\"\n               << (profile_gemm ? \"true\" : \"false\") << \",\\\"source_sha256\\\":\" << quoted(GUIDE_SOURCE_SHA256)\n               << \",\\\"cuda_runtime_version\\\":\" << runtime << \",\\\"driver_version\\\":\" << driver\n               << \",\\\"device\\\":{\\\"name\\\":\" << quoted(device.name) << \",\\\"compute_capability\\\":[\" << device.major << ',' << device.minor\n               << \"]},\\\"atol\\\":1e-5,\\\"rtol\\\":1e-5,\\\"cases\\\":[\";\n        for (size_t i=0;i<results.size();++i) { if (i) report << ','; report << results[i]; }\n        report << \"],\\\"negative_control\\\":{\\\"kind\\\":\\\"skip_normalization\\\",\\\"executed\\\":\"\n               << (profile_gemm ? \"false\" : \"true\") << \",\\\"observed\\\":\" << array(wrong) << \"}}\";\n        emit(report.str(),filename);\n        return 0;\n    } catch (const std::exception& error) {\n        std::cerr << \"cuda_lab: \" << error.what() << '\\n';\n        return 1;\n    }\n}\n","reference.py":"#!/usr/bin/env python3\n\"\"\"Independent standard-library oracle for cuda_lab.cu readback reports.\n\nThis program never invokes CUDA. Its self-test uses synthetic host records and\ntherefore never provides evidence of device execution.\n\"\"\"\nimport argparse\nimport copy\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nimport struct\nimport sys\n\nATOL = RTOL = 1e-5\nHERE = Path(__file__).resolve().parent\n\n\ndef source_sha256(path):\n    return hashlib.sha256(Path(path).read_bytes()).hexdigest()\n\n\ndef softmax(values):\n    maximum = max(values)\n    numerators = [math.exp(value - maximum) for value in values]\n    denominator = math.fsum(numerators)\n    return [value / denominator for value in numerators]\n\n\ndef fixtures():\n    \"\"\"Reconstruct inputs and answers without using the C++ reported answers.\"\"\"\n    cases = {}\n    for cols in (1, 5, 129, 257):\n        rows = [[(((row + 1) * 11 + col * 7) % 29 - 14) / 4.0\n                 + row * 0.125 for col in range(cols)] for row in range(3)]\n        cases['sum-' + str(cols)] = ([3, cols], [math.fsum(row) for row in rows])\n        cases['softmax-' + str(cols)] = ([3, cols],\n                                        [value for row in rows for value in softmax(row)])\n    cases['softmax-extreme'] = ([1, 5], softmax([1000., 1001., 999., -1000., 0.]))\n    for m, k, n in ((1, 1, 1), (17, 19, 13), (32, 32, 32), (31, 33, 29)):\n        a = [[((row * 3 + col * 5) % 17 - 8) / 8.0 for col in range(k)] for row in range(m)]\n        b = [[((row * 7 + col * 2) % 19 - 9) / 16.0 for col in range(n)] for row in range(k)]\n        answer = [math.fsum(a[row][inner] * b[inner][col] for inner in range(k))\n                  for row in range(m) for col in range(n)]\n        cases['gemm-%d-%d-%d' % (m, k, n)] = ([m, k, n], answer)\n    return cases\n\n\ndef require(condition, message):\n    if not condition:\n        raise ValueError(message)\n\n\ndef number(value, label):\n    require(type(value) in (int, float) and math.isfinite(value), 'nonfinite_or_invalid:' + label)\n    return float(value)\n\n\ndef vector(actual, expected, label):\n    require(type(actual) is list and len(actual) == len(expected), 'wrong_output_size:' + label)\n    errors = []\n    for index, (got, wanted) in enumerate(zip(actual, expected)):\n        got = number(got, '%s[%d]' % (label, index))\n        error = abs(got - wanted)\n        require(error <= ATOL + RTOL * abs(wanted), 'wrong_value:%s[%d]' % (label, index))\n        errors.append(error)\n    return max(errors, default=0.)\n\n\ndef validate(report, expected_source):\n    require(type(report) is dict, 'report_not_object')\n    require(type(report.get('schema_version')) is int and report['schema_version'] == 1, 'wrong_schema')\n    require(report.get('status') == 'passed', 'report_not_passed')\n    require(report.get('device_execution') is True, 'device_execution_not_reported')\n    require(report.get('profile_only') is False, 'profile_only_or_unspecified')\n    require(report.get('source_sha256') == expected_source and len(expected_source) == 64, 'source_mismatch')\n    require(number(report.get('atol'), 'atol') == ATOL and number(report.get('rtol'), 'rtol') == RTOL,\n            'wrong_tolerance')\n    for field in ('cuda_runtime_version', 'driver_version'):\n        require(type(report.get(field)) is int and report[field] > 0, 'invalid_' + field)\n    device = report.get('device')\n    require(type(device) is dict and type(device.get('name')) is str and bool(device['name']), 'invalid_device')\n    cc = device.get('compute_capability')\n    require(type(cc) is list and len(cc) == 2 and all(type(x) is int and x >= 0 for x in cc)\n            and cc[0] >= 8, 'invalid_compute_capability')\n    expected = fixtures()\n    cases = report.get('cases')\n    require(type(cases) is list and len(cases) == len(expected) == 13, 'wrong_case_count')\n    seen, checked_values, maximum_error = set(), 0, 0.\n    for case in cases:\n        require(type(case) is dict, 'case_not_object')\n        name = case.get('fixture')\n        require(type(name) is str and name in expected and name not in seen, 'unknown_or_duplicate_case')\n        seen.add(name)\n        shape, answer = expected[name]\n        require(type(case.get('shape')) is list and all(type(x) is int for x in case['shape'])\n                and case['shape'] == shape, 'wrong_shape:' + name)\n        require(type(case.get('elements')) is int and case['elements'] == len(answer), 'wrong_elements:' + name)\n        error = vector(case.get('values'), answer, name)\n        declared = number(case.get('max_abs_error'), name + '.max_abs_error')\n        require(declared >= 0 and math.isclose(declared, error, rel_tol=1e-6, abs_tol=1e-12),\n                'wrong_error_summary:' + name)\n        maximum_error = max(maximum_error, error)\n        checked_values += len(answer)\n    require(seen == set(expected), 'missing_case')\n    negative = report.get('negative_control')\n    require(type(negative) is dict and negative.get('kind') == 'skip_normalization'\n            and negative.get('executed') is True, 'negative_control_not_executed')\n    unnormalized = [math.exp(value - 1001.) for value in (1000., 1001., 999., -1000., 0.)]\n    vector(negative.get('observed'), unnormalized, 'negative_control')\n    correct = expected['softmax-extreme'][1]\n    require(any(abs(got - wanted) > ATOL + RTOL * abs(wanted)\n                for got, wanted in zip(negative['observed'], correct)), 'negative_control_not_rejected')\n    return {'status': 'passed', 'source_sha256': expected_source, 'fixtures': len(seen),\n            'readback_values_checked': checked_values, 'negative_values_checked': len(correct),\n            'max_abs_error': maximum_error, 'device_execution': True,\n            'scope': 'Independent host validation of supplied complete device readbacks; no kernels launched by this validator.'}\n\n\ndef float32(value):\n    return struct.unpack('<f', struct.pack('<f', value))[0]\n\n\ndef synthetic_record(expected_source):\n    cases = []\n    for name, (shape, expected) in fixtures().items():\n        actual = [float32(value) for value in expected]\n        cases.append({'fixture': name, 'shape': shape, 'elements': len(actual), 'values': actual,\n                      'max_abs_error': max(abs(x - y) for x, y in zip(actual, expected))})\n    return {'schema_version': 1, 'status': 'passed', 'device_execution': True, 'profile_only': False,\n            'source_sha256': expected_source, 'cuda_runtime_version': 12090, 'driver_version': 12090,\n            'device': {'name': 'SYNTHETIC HOST RECORD, NOT A DEVICE', 'compute_capability': [8, 0]},\n            'atol': ATOL, 'rtol': RTOL, 'cases': cases,\n            'negative_control': {'kind': 'skip_normalization', 'executed': True,\n                                 'observed': [float32(math.exp(x - 1001.))\n                                              for x in (1000., 1001., 999., -1000., 0.)]}}\n\n\ndef selftest(expected_source):\n    good = synthetic_record(expected_source)\n    summary = validate(good, expected_source)\n    mutations = {\n        'wrong_shape': lambda r: r['cases'][0]['shape'].__setitem__(0, 2),\n        'wrong_value': lambda r: r['cases'][0]['values'].__setitem__(0, 12345.),\n        'missing_case': lambda r: r['cases'].pop(),\n        'duplicate_case': lambda r: r['cases'].__setitem__(1, copy.deepcopy(r['cases'][0])),\n        'profile_only': lambda r: r.__setitem__('profile_only', True),\n        'source_mismatch': lambda r: r.__setitem__('source_sha256', '0' * 64),\n        'nonfinite_value': lambda r: r['cases'][0]['values'].__setitem__(0, float('nan')),\n        'empty_readbacks': lambda r: r['cases'][0].__setitem__('values', []),\n        'wrong_elements': lambda r: r['cases'][0].__setitem__('elements', 100),\n        'wrong_error_summary': lambda r: r['cases'][0].__setitem__('max_abs_error', 1.),\n        'loosened_tolerance': lambda r: r.__setitem__('atol', 10.),\n        'no_device_execution': lambda r: r.__setitem__('device_execution', False),\n        'negative_not_executed': lambda r: r['negative_control'].__setitem__('executed', False),\n        'negative_normalized': lambda r: r['negative_control'].__setitem__('observed', fixtures()['softmax-extreme'][1]),\n        'negative_wrong_value': lambda r: r['negative_control']['observed'].__setitem__(0, 5.),\n        'negative_nonfinite': lambda r: r['negative_control']['observed'].__setitem__(0, float('inf')),\n    }\n    rejected = []\n    for name, mutate in mutations.items():\n        bad = copy.deepcopy(good)\n        mutate(bad)\n        try:\n            validate(bad, expected_source)\n        except ValueError:\n            rejected.append(name)\n        else:\n            raise AssertionError('validator accepted mutation: ' + name)\n    return {'status': 'passed', 'device_execution': False, 'source_sha256': expected_source,\n            'synthetic_fixtures': summary['fixtures'], 'synthetic_values_checked': summary['readback_values_checked'],\n            'mutations_rejected': rejected, 'scope': 'CPU-only synthetic-record validator self-test; no GPU execution.'}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--source', type=Path, default=HERE / 'cuda_lab.cu')\n    parser.add_argument('--check-gpu', '--report', dest='report', type=Path,\n                        help='Full default CUDA run report to validate, not a probe or profile report')\n    parser.add_argument('--self-test', '--selftest', dest='selftest', action='store_true')\n    parser.add_argument('--json', type=Path, help='Write validator summary as JSON')\n    args = parser.parse_args()\n    if args.selftest == bool(args.report):\n        parser.error('choose exactly one of --self-test or --check-gpu FILE')\n    try:\n        expected_source = source_sha256(args.source)\n        if args.selftest:\n            summary = selftest(expected_source)\n        else:\n            summary = validate(json.loads(args.report.read_text()), expected_source)\n        text = json.dumps(summary, indent=2, allow_nan=False) + '\\n'\n        if args.json:\n            args.json.parent.mkdir(parents=True, exist_ok=True)\n            args.json.write_text(text)\n        print(text, end='')\n        return 0\n    except (ValueError, OSError, AssertionError) as error:\n        print('reference: ' + str(error), file=sys.stderr)\n        return 1\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n","build.py":"#!/usr/bin/env python3\n\"\"\"Build the pinned Linux x86_64 CUDA lab and probe without launching kernels.\"\"\"\nimport argparse\nimport datetime\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport platform\nimport re\nimport shlex\nimport shutil\nimport subprocess\nimport sys\nimport tarfile\nimport tempfile\nimport time\nimport urllib.request\n\nHERE = Path(__file__).resolve().parent\nREDIST = 'https://developer.download.nvidia.com/compute/cuda/redist/'\nCORE = ('cuda_lab.cu', 'reference.py', 'build.py', 'toolchain-lock.json')\nCOMPONENTS = {'cuda_nvcc', 'cuda_cudart', 'cuda_cccl'}\nENTRIES = {'row_sum_kernel', 'row_softmax_kernel', 'tiled_matmul_kernel'}\n\n\ndef sha256(path):\n    digest = hashlib.sha256()\n    with Path(path).open('rb') as stream:\n        for block in iter(lambda: stream.read(1024 * 1024), b''):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef require(condition, message):\n    if not condition:\n        raise ValueError(message)\n\n\ndef core_hashes():\n    return {name: sha256(HERE / name) for name in CORE}\n\n\ndef download(url, destination, expected_sha, expected_size=None, allow_network=True):\n    \"\"\"Every cached or downloaded byte is checked before use.\"\"\"\n    destination = Path(destination)\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    if destination.is_file() and sha256(destination) == expected_sha:\n        if expected_size is None or destination.stat().st_size == expected_size:\n            return destination\n    require(allow_network, 'verified_archive_not_cached; use --fetch-toolkit:' + str(destination))\n    partial = destination.with_name(destination.name + '.part')\n    limit = expected_size if expected_size is not None else 5 * 1024 * 1024\n    for attempt in range(3):\n        try:\n            request = urllib.request.Request(url, headers={'User-Agent': 'InfraGuide-CUDA-pinned-build/1'})\n            digest, size = hashlib.sha256(), 0\n            with urllib.request.urlopen(request, timeout=90) as response, partial.open('wb') as output:\n                for block in iter(lambda: response.read(1024 * 1024), b''):\n                    size += len(block)\n                    require(size <= limit, 'download_exceeds_locked_size:' + url)\n                    digest.update(block)\n                    output.write(block)\n            require(expected_size is None or size == expected_size, 'download_size_mismatch:' + url)\n            require(digest.hexdigest() == expected_sha, 'download_sha256_mismatch:' + url)\n            partial.replace(destination)\n            return destination\n        except (OSError, ValueError):\n            partial.unlink(missing_ok=True)\n            if attempt == 2:\n                raise\n            time.sleep(2 ** attempt)\n\n\ndef safe_extract(archive, destination, expected_root):\n    \"\"\"Inspect all paths first; allow only contained regular files and links.\n\n    The inspected NVIDIA archives have one *-archive root and include/, lib/,\n    bin/, nvvm/ trees. Their four library symlinks name same-directory basenames.\n    No tarfile extraction method is used, and no write traverses a symlink.\n    \"\"\"\n    destination = Path(destination)\n    require(not destination.exists(), 'extraction_destination_exists')\n    with tarfile.open(archive, 'r:xz') as tar:\n        members = tar.getmembers()\n        by_path, total = {}, 0\n        for member in members:\n            path = PurePosixPath(member.name)\n            require(not path.is_absolute() and path.parts and path.parts[0] == expected_root\n                    and '..' not in path.parts and '\\\\' not in member.name, 'unsafe_archive_path:' + member.name)\n            require(path not in by_path, 'duplicate_archive_path:' + member.name)\n            require(member.isdir() or member.isfile() or member.issym(), 'unsupported_archive_member:' + member.name)\n            by_path[path] = member\n            total += member.size\n            require(total <= 2 * 1024 ** 3 and len(by_path) <= 100000, 'archive_expansion_limit')\n            if member.issym():\n                target = PurePosixPath(member.linkname)\n                require(bool(member.linkname) and len(target.parts) == 1 and member.linkname not in ('.', '..')\n                        and '/' not in member.linkname and '\\\\' not in member.linkname,\n                        'archive_link_must_name_same_directory_file')\n        for path, member in by_path.items():\n            require(all(not by_path[parent].issym() for parent in path.parents if parent in by_path),\n                    'archive_symlink_parent:' + str(path))\n            if member.issym():\n                visited, current = set(), path\n                while by_path[current].issym():\n                    require(current not in visited, 'cyclic_archive_link:' + str(path))\n                    visited.add(current)\n                    current = current.parent / by_path[current].linkname\n                    require(current in by_path, 'dangling_archive_link:' + str(path))\n                require(by_path[current].isfile(), 'archive_link_target_not_regular_file:' + str(path))\n        destination.mkdir(parents=True)\n        for path, member in by_path.items():\n            target = destination.joinpath(*path.parts)\n            if member.isdir():\n                target.mkdir(parents=True, exist_ok=True)\n            elif member.isfile():\n                target.parent.mkdir(parents=True, exist_ok=True)\n                with tar.extractfile(member) as source, target.open('xb') as output:\n                    shutil.copyfileobj(source, output)\n                target.chmod(member.mode & 0o777)\n        for path, member in by_path.items():\n            if member.issym():\n                target = destination.joinpath(*path.parts)\n                target.parent.mkdir(parents=True, exist_ok=True)\n                target.symlink_to(member.linkname)\n    return {'archive_root': expected_root, 'members': len(members), 'regular_file_bytes': total,\n            'relative_symlinks': sum(member.issym() for member in members)}\n\n\ndef archive_selftest():\n    \"\"\"Exercise the link graph, including a lexical-normalization escape.\"\"\"\n    rejected = []\n    cases = {\n        'linked_parent_escape': [('r/d/up', '..'), ('r/d/escape', 'up/../..')],\n        'link_cycle': [('r/a', 'b'), ('r/b', 'a')],\n        'dangling_link': [('r/a', 'missing')],\n        'absolute_link': [('r/a', '/tmp/outside')],\n    }\n    with tempfile.TemporaryDirectory(prefix='cuda-archive-selftest-') as temporary:\n        root = Path(temporary)\n        for name, links in cases.items():\n            archive = root / (name + '.tar.xz')\n            with tarfile.open(archive, 'w:xz') as tar:\n                for path, target in links:\n                    member = tarfile.TarInfo(path)\n                    member.type, member.linkname = tarfile.SYMTYPE, target\n                    tar.addfile(member)\n            try:\n                safe_extract(archive, root / name, 'r')\n            except ValueError:\n                rejected.append(name)\n            else:\n                raise ValueError('archive_selftest_accepted:' + name)\n        archive = root / 'valid-chain.tar.xz'\n        with tarfile.open(archive, 'w:xz') as tar:\n            member = tarfile.TarInfo('r/lib.so.1.0')\n            member.size = 1\n            tar.addfile(member, io.BytesIO(b'x'))\n            for path, target in [('r/lib.so.1', 'lib.so.1.0'), ('r/lib.so', 'lib.so.1')]:\n                member = tarfile.TarInfo(path)\n                member.type, member.linkname = tarfile.SYMTYPE, target\n                tar.addfile(member)\n        safe_extract(archive, root / 'valid-chain', 'r')\n        require((root / 'valid-chain/r/lib.so').read_bytes() == b'x', 'archive_selftest_valid_chain_failed')\n    return {'status': 'passed', 'device_execution': False, 'mutations_rejected': rejected,\n            'same_directory_chain_accepted': True}\n\n\ndef merge_tree(source, destination):\n    \"\"\"Merge the verified include/lib trees without replacing different files.\"\"\"\n    destination.mkdir(parents=True, exist_ok=True)\n    for child in source.iterdir():\n        target = destination / child.name\n        if child.is_symlink():\n            if target.is_symlink():\n                require(os.readlink(target) == os.readlink(child), 'merge_symlink_collision:' + str(target))\n            else:\n                require(not target.exists(), 'merge_path_collision:' + str(target))\n                target.symlink_to(os.readlink(child))\n        elif child.is_dir():\n            require(not target.is_symlink() and (not target.exists() or target.is_dir()), 'merge_directory_collision')\n            merge_tree(child, target)\n        else:\n            require(not target.is_symlink(), 'merge_file_symlink_collision')\n            if target.exists():\n                require(target.is_file() and sha256(target) == sha256(child), 'merge_file_collision:' + str(target))\n            else:\n                shutil.copy2(child, target)\n\n\ndef command(argv, record, output_dir, label, accepted=(0,), env=None):\n    entry = {'label': label, 'argv': [str(x) for x in argv], 'shell_display': shlex.join([str(x) for x in argv])}\n    record['commands'].append(entry)\n    result = subprocess.run(entry['argv'], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                            timeout=600, env=env)\n    entry.update({'returncode': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr})\n    (output_dir / (label + '.log')).write_text(result.stdout + result.stderr)\n    require(result.returncode in accepted, 'command_failed:' + label + ':' + str(result.returncode))\n    return result\n\n\ndef build(args, record, output_dir):\n    record['archive_safety_selftest'] = archive_selftest()\n    cpu_path = output_dir / 'cpu-selftest.json'\n    command([sys.executable, '-B', HERE / 'reference.py', '--self-test', '--json', cpu_path],\n            record, output_dir, 'cpu-selftest')\n    record['cpu_selftest'] = json.loads(cpu_path.read_text())\n    require(record['cpu_selftest']['device_execution'] is False, 'selftest_claimed_device_execution')\n    if args.host_selftest:\n        record.update(status='host-selftest-passed', compilation={'status': 'not-run', 'reason': 'host-selftest option'})\n        return 0\n    if platform.system() != 'Linux' or platform.machine().lower() not in ('x86_64', 'amd64'):\n        record.update(status='not-run', compilation={'status': 'not-run', 'reason': 'requires Linux x86_64'})\n        return 2\n    lock = json.loads((HERE / 'toolchain-lock.json').read_text())\n    require(lock['cuda_release'] == '12.9.1' and lock['target'] == 'linux-x86_64', 'unexpected_toolchain_target')\n    require(set(lock['components']) == COMPONENTS, 'unexpected_toolkit_components')\n    require(lock['manifest_url'] == REDIST + 'redistrib_12.9.1.json', 'unexpected_manifest_url')\n    cache = args.cache_dir.resolve()\n    manifest_path = download(lock['manifest_url'], cache / 'redistrib_12.9.1.json', lock['manifest_sha256'],\n                             allow_network=args.fetch_toolkit)\n    manifest = json.loads(manifest_path.read_text())\n    require(manifest['release_label'] == '12.9.1', 'manifest_release_mismatch')\n    toolkit = cache / ('toolkit-' + record['core_sha256']['toolchain-lock.json'])\n    record['toolkit'] = {'release': lock['cuda_release'], 'target': lock['target'],\n                         'manifest_url': lock['manifest_url'], 'manifest_sha256': sha256(manifest_path),\n                         'components': {}}\n    # A new staging directory avoids trusting a pre-existing extracted toolchain.\n    with tempfile.TemporaryDirectory(prefix='cuda-stage-', dir=cache) as temporary:\n        stage = Path(temporary)\n        merged = stage / 'merged'\n        merged.mkdir()\n        for name in sorted(COMPONENTS):\n            component = lock['components'][name]\n            official = manifest[name][lock['target']]\n            require(all(str(component[key]) == str(official[key]) for key in ('relative_path', 'sha256', 'size')),\n                    'component_manifest_mismatch:' + name)\n            relative = PurePosixPath(component['relative_path'])\n            require(not relative.is_absolute() and '..' not in relative.parts\n                    and relative.parts[:2] == (name, lock['target']) and relative.name.endswith('.tar.xz'),\n                    'unsafe_component_url:' + name)\n            archive = download(REDIST + str(relative), cache / relative.name,\n                               component['sha256'], int(component['size']), allow_network=args.fetch_toolkit)\n            root_name = relative.name[:-len('.tar.xz')]\n            extracted = stage / name\n            layout = safe_extract(archive, extracted, root_name)\n            root = extracted / root_name\n            licenses = merged / 'licenses' / name\n            licenses.mkdir(parents=True)\n            for child in list(root.iterdir()):\n                if child.name.upper().startswith('LICENSE'):\n                    child.rename(licenses / child.name)\n            merge_tree(root, merged)\n            record['toolkit']['components'][name] = dict(component, version=manifest[name]['version'], **layout)\n        if toolkit.exists():\n            shutil.rmtree(toolkit)\n        merged.rename(toolkit)\n    for relative in ('bin/nvcc', 'bin/ptxas', 'nvvm/bin/cicc', 'nvvm/libdevice/libdevice.10.bc',\n                     'include/cuda_runtime.h', 'lib/libcudart_static.a', 'lib/libcudadevrt.a'):\n        require((toolkit / relative).is_file(), 'toolkit_missing:' + relative)\n    nvcc = toolkit / 'bin/nvcc'\n    gxx = shutil.which(args.host_compiler)\n    require(gxx is not None, 'missing_host_compiler:' + args.host_compiler)\n    env = dict(os.environ)\n    env['PATH'] = str(toolkit / 'bin') + os.pathsep + env.get('PATH', '')\n    record['nvcc_version'] = command([nvcc, '--version'], record, output_dir, 'nvcc-version', env=env).stdout\n    require('release 12.9' in record['nvcc_version'] and 'V12.9.86' in record['nvcc_version'], 'nvcc_version_mismatch')\n    record['gcc_version'] = command([gxx, '--version'], record, output_dir, 'gcc-version', env=env).stdout\n    source = HERE / 'cuda_lab.cu'\n    common = [nvcc, '-std=c++17', '-O2', '-lineinfo', '--compiler-bindir', gxx,\n              '-I' + str(toolkit / 'include'), '-L' + str(toolkit / 'lib'),\n              '-DGUIDE_SOURCE_SHA256=\"' + record['core_sha256']['cuda_lab.cu'] + '\"']\n    binary, ptx = output_dir / 'cuda_lab', output_dir / 'cuda_lab.ptx'\n    command(common + ['--cudart=static', '-gencode=arch=compute_80,code=sm_80',\n                      '-gencode=arch=compute_80,code=compute_80', source, '-o', binary],\n            record, output_dir, 'compile-binary', env=env)\n    command(common + ['--ptx', '-arch=compute_80', source, '-o', ptx],\n            record, output_dir, 'compile-ptx', env=env)\n    entries = set(re.findall(r'\\.entry\\s+([A-Za-z_][A-Za-z_0-9]*)\\s*\\(', ptx.read_text()))\n    require(ENTRIES <= entries, 'missing_ptx_kernel_entry')\n    require(all(name.encode() in binary.read_bytes() for name in ENTRIES), 'missing_binary_kernel_name')\n    record['compilation'] = {'status': 'passed', 'binary': {'path': binary.name, 'sha256': sha256(binary),\n                              'bytes': binary.stat().st_size, 'targets': ['sm_80', 'compute_80']},\n                             'ptx': {'path': ptx.name, 'sha256': sha256(ptx), 'bytes': ptx.stat().st_size,\n                                     'target': 'compute_80', 'verified_entries': sorted(ENTRIES)}}\n    help_result = command([binary, '--help'], record, output_dir, 'binary-help', env=env)\n    require('--probe-only' in help_result.stdout and '13 small GPU correctness fixtures' in help_result.stdout,\n            'binary_help_mismatch')\n    probe_path = output_dir / 'device-probe.json'\n    probe_result = command([binary, '--probe-only', '--json', probe_path], record, output_dir,\n                           'device-probe', accepted=(0, 2), env=env)\n    probe = json.loads(probe_path.read_text())\n    require(probe.get('device_execution') is False, 'probe_claimed_kernel_execution')\n    require(probe.get('source_sha256') == record['core_sha256']['cuda_lab.cu'], 'probe_source_mismatch')\n    require(type(probe.get('device_count')) is int and probe['device_count'] >= 0, 'invalid_probe_count')\n    require((probe_result.returncode == 0 and probe.get('status') == 'device-detected' and probe['device_count'] > 0)\n            or (probe_result.returncode == 2 and probe.get('status') == 'not-run'), 'invalid_probe_result')\n    record['device_probe'] = dict(probe, returncode=probe_result.returncode)\n    record['status'] = 'passed'\n    return 0\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--output-dir', type=Path, default=Path('build'))\n    parser.add_argument('--cache-dir', type=Path, default=Path.home() / '.cache/infra-guide/cuda-core')\n    parser.add_argument('--host-compiler', default='g++')\n    parser.add_argument('--fetch-toolkit', action='store_true', help='Download locked official components if not already cached')\n    parser.add_argument('--host-selftest', action='store_true', help='Run only the CPU oracle self-test on any host')\n    args = parser.parse_args()\n    output_dir = args.output_dir.resolve()\n    output_dir.mkdir(parents=True, exist_ok=True)\n    record = {'schema_version': 1, 'status': 'started', 'device_execution': False,\n              'started_at_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),\n              'host': {'system': platform.system(), 'machine': platform.machine(), 'python': platform.python_version()},\n              'core_sha256': core_hashes(), 'commands': [],\n              'scope': 'Pinned CUDA compilation, CPU oracle self-test, executable help and availability probe only; no kernels launched.'}\n    try:\n        exit_code = build(args, record, output_dir)\n        require(core_hashes() == record['core_sha256'], 'core_files_changed_during_build')\n    except (OSError, ValueError, subprocess.SubprocessError, KeyError, tarfile.TarError) as error:\n        record.update(status='failed', error=type(error).__name__ + ': ' + str(error))\n        exit_code = 1\n    record['finished_at_utc'] = datetime.datetime.now(datetime.timezone.utc).isoformat()\n    destination = output_dir / 'build-record.json'\n    destination.write_text(json.dumps(record, indent=2, allow_nan=False) + '\\n')\n    print(json.dumps({'status': record['status'], 'device_execution': False, 'record': str(destination)}))\n    return exit_code\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n","toolchain-lock.json":"{\n  \"cuda_release\": \"12.9.1\",\n  \"target\": \"linux-x86_64\",\n  \"manifest_url\": \"https://developer.download.nvidia.com/compute/cuda/redist/redistrib_12.9.1.json\",\n  \"manifest_sha256\": \"8335301010b0023ee1ff61eb11e2600ca62002d76780de4089011ad77e0c7630\",\n  \"components\": {\n    \"cuda_nvcc\": {\n      \"relative_path\": \"cuda_nvcc/linux-x86_64/cuda_nvcc-linux-x86_64-12.9.86-archive.tar.xz\",\n      \"sha256\": \"7a1a5b652e5ef85c82b721d10672fc9a2dbaab44e9bd3c65a69517bf53998c35\",\n      \"size\": \"81100244\"\n    },\n    \"cuda_cudart\": {\n      \"relative_path\": \"cuda_cudart/linux-x86_64/cuda_cudart-linux-x86_64-12.9.79-archive.tar.xz\",\n      \"sha256\": \"1f6ad42d4f530b24bfa35894ccf6b7209d2354f59101fd62ec4a6192a184ce99\",\n      \"size\": \"1514676\"\n    },\n    \"cuda_cccl\": {\n      \"relative_path\": \"cuda_cccl/linux-x86_64/cuda_cccl-linux-x86_64-12.9.27-archive.tar.xz\",\n      \"sha256\": \"8b1a5095669e94f2f9afd7715533314d418179e9452be61e2fde4c82a3e542aa\",\n      \"size\": \"997888\"\n    }\n  }\n}\n","README.md":"# CUDA 算子：从数据契约到设备回读\n\n这是一份教学实现：逐行求和、稳定 softmax、16×16 分块矩阵乘法。输入为有限 float32、连续行主序、正尺寸；不含掩码、Tensor Core 或自动调优。源码中的线程数与共享内存大小是固定契约。\n\n## 编译与执行分开\n\nLinux x86_64、Python 3.9+、可用的 C++ 主机编译器。构建脚本按 `toolchain-lock.json` 下载并校验 NVIDIA 官方 CUDA 12.9.1 组件，约 83 MB。已有缓存同样检查大小与 SHA256。脚本只编译、链接并探测设备，不发起内核。\n\n```sh\npython3 reference.py --self-test\npython3 build.py --fetch-toolkit --output-dir build\n```\n\n要在 NVIDIA GPU 上执行，另需兼容 CUDA 12.9 的驱动及计算能力 8.0 或更新的设备。本包包含 sm_80 机器码与 compute_80 PTX；目标驱动仍须能够处理相应代码。\n\n```sh\n./build/cuda_lab --json gpu-results.json\npython3 reference.py --check-gpu gpu-results.json\n```\n\n程序回读 13 组正例的每个输出及一组故意不归一化的 softmax 结果；后者必须与正确结果不同。独立 Python 校验器重新生成输入和参考，逐项要求 `abs(actual-reference) <= 1e-5 + 1e-5*abs(reference)`，同时检查形状、组数、源码摘要和负例。它检查报告中的数值与结构，不为外部 JSON 的硬件来源背书。\n\n- 求和及 softmax：3 行，列数分别 1、5、129、257，共 8 组。\n- 稳定 softmax：`[1000,1001,999,-1000,0]`，1 组，加错误归一化对照。\n- GEMM：`M,K,N` 为 `(1,1,1)`、`(17,19,13)`、`(32,32,32)`、`(31,33,29)`，共 4 组。\n\n没有设备时，程序记录 `status: not-run`、`device_execution: false`，退出码 2。`--probe-only` 仅查询设备；即使发现设备也不发起内核。CPU oracle 自检用合成报告与错误变异，始终标注 `device_execution: false`，不代替 GPU 数值验证。\n\n## 先验证正确，再采集性能\n\n具备 Nsight 工具与目标设备时可选做：\n\n```sh\nnsys profile --trace=cuda --output=gemm-timeline ./build/cuda_lab --profile-gemm\nncu --kernel-name-base function --kernel-name tiled_matmul_kernel \\\n  --set basic --export gemm-kernel ./build/cuda_lab --profile-gemm\n```\n\n`--profile-gemm` 只执行一个 512³ GEMM 并检查结果；不提供完整 13 组验收，独立校验器会拒绝把该模式的报告当完整通过。程序没有报告 GPU 加速比。额外采集会改变执行开销，轨迹与无采集计时需要分别解释。\n\n## 当前证据\n\n`validation.json` 指向真实 Linux CI、不可变源码提交、编译输出与 PTX 入口。`compile-record.json` 是原始构建记录，`host-oracle.json` 是 CPU 校验器自检记录；这些记录不代表 GPU 内核已运行。本站尚无此实验的 GPU 数值回读、Nsight 轨迹或性能结论。\n\n官方依据：[CUDA 12.9.1 编程指南](https://docs.nvidia.com/cuda/archive/12.9.1/cuda-c-programming-guide/index.html)、[NVCC 12.9.1](https://docs.nvidia.com/cuda/archive/12.9.1/cuda-compiler-driver-nvcc/index.html)。\n"};
